class BinOp(Expr):
    _fields = ("left", "op", "right")        # named children, as in ast
    def __init__(self, left, op, right):
        self.left, self.op, self.right = left, op, right

def walk(node):
    if isinstance(node, BinOp):               # per-node traversal
        walk(node.left)
        walk(node.right)
